//! Types and abstractions for HTTP responses generated on this server or
//! obtained from an upstream server.

use bytes::Bytes;
use http_body_util::combinators::BoxBody;
use hyper::{
    Version,
    header::{self, HeaderValue},
    Response,
};

use crate::config;

/// Common type for all responses, since [`Response`] is generic but we don't
/// need so much flexibility at a proxy level. Most of the times the real
/// response is generated by the target server and we just send it back to
/// the client.
pub(crate) type BoxBodyResponse = Response<BoxBody<Bytes, hyper::Error>>;

/// Response sent back to the client at the end of the proxying process. It
/// wraps the response received by the target server and when necessary we can
/// call [`ProxyResponse::into_forwarded`] to obtain the final response.
pub(crate) struct ProxyResponse<T> {
    /// Original response received from a server behind this proxy.
    response: Response<T>,

    /// Response header customization.
    headers: config::ResponseHeaders,

    /// Via member to append when enabled.
    via_member: String,
}

impl<T> ProxyResponse<T> {
    /// Creates a new [`ProxyResponse`], wrapping the original response.
    pub fn new(
        response: Response<T>,
        headers: config::ResponseHeaders,
        received_by: String,
    ) -> Self {
        let via_member = format!("{} {}", version_token(response.version()), received_by);
        Self {
            response,
            headers,
            via_member,
        }
    }

    /// Consumes this [`ProxyResponse`] and returns the final response that
    /// should be sent to the client.
    pub fn into_forwarded(mut self) -> Response<T> {
        if self.headers.server.should_override {
            self.response.headers_mut().insert(
                header::SERVER,
                HeaderValue::from_str(rxh_server_header(self.headers.server.version).as_str()).unwrap(),
            );
        }

        if self.headers.via.extend {
            append_list_header(self.response.headers_mut(), header::VIA, &self.via_member);
        }

        for (name, value) in &self.headers.set {
            if let Ok(name) = header::HeaderName::from_bytes(name.as_bytes())
                && let Ok(value) = HeaderValue::from_str(value)
            {
                self.response.headers_mut().insert(name, value);
            }
        }

        for name in &self.headers.remove {
            if let Ok(name) = header::HeaderName::from_bytes(name.as_bytes()) {
                self.response.headers_mut().remove(name);
            }
        }

        self.response
    }
}

/// HTTP response originated on this server, not obtained through a proxy
/// process.
pub(crate) struct LocalResponse;

impl LocalResponse {
    /// Response builder pre-initialized with our header values.
    pub fn builder() -> http::response::Builder {
        Response::builder().header(header::SERVER, rxh_server_header(true))
    }

    /// Generic `HTTP 404 Not Found` response.
    pub fn not_found() -> BoxBodyResponse {
        Self::builder()
            .status(http::StatusCode::NOT_FOUND)
            .header(header::CONTENT_TYPE, "text/plain")
            .body(super::body::full("HTTP 404 NOT FOUND"))
            .unwrap()
    }

    pub fn bad_gateway() -> BoxBodyResponse {
        Self::builder()
            .status(http::StatusCode::BAD_GATEWAY)
            .header(header::CONTENT_TYPE, "text/plain")
            .body(super::body::full("HTTP 502 BAD GATEWAY"))
            .unwrap()
    }
}

/// Let everybody know who is running this server ;)
///
/// ```http
/// HTTP/2 200 OK
/// Server: rxh/0.1.0
/// Content-Type: text/plain; charset=utf-8
/// Content-Length: 11
/// Date: Sat, 07 Jan 2023 01:46:50 GMT
///
/// Hello World
/// ```
///
/// TODO: Allow configuration for this header (no version, custom string, etc).
#[inline]
pub(crate) fn rxh_server_header(with_version: bool) -> String {
    if with_version {
        format!("rxh/{}", crate::VERSION)
    } else {
        String::from("rxh")
    }
}

fn version_token(version: Version) -> &'static str {
    match version {
        Version::HTTP_09 => "0.9",
        Version::HTTP_10 => "1.0",
        Version::HTTP_11 => "1.1",
        Version::HTTP_2 => "2",
        Version::HTTP_3 => "3",
        _ => "1.1",
    }
}

fn combine_header_values(headers: &hyper::HeaderMap, name: header::HeaderName) -> Option<String> {
    let mut values = vec![];

    for value in headers.get_all(name) {
        if let Ok(value) = value.to_str() {
            values.push(value.trim().to_string());
        }
    }

    if values.is_empty() {
        None
    } else {
        Some(values.join(", "))
    }
}

fn append_list_header(headers: &mut hyper::HeaderMap, name: header::HeaderName, value: &str) {
    let new_value = if let Some(previous) = combine_header_values(headers, name.clone()) {
        format!("{previous}, {value}")
    } else {
        value.to_string()
    };

    headers.insert(name, HeaderValue::from_str(&new_value).unwrap());
}
